local function C_9()
	local script = LMG2L["LocalScript_9"];
	local TweenService = game:GetService("TweenService")	
	local button = script.Parent	
	local label = button.Parent:FindFirstChild("CounterDisplay")	

	-- A list of "tickle" responses	
	local tickleWords = {"Hee hee!", "Haha!", "Stop it!", "Lol!", "Tee hee!", "LOL!", "Hehe!", "Stop!", "Aha!", "Hahaha!"}	
	local clicks = 0	

	local function doTickleWobble()	
		local info = TweenInfo.new(0.05, Enum.EasingStyle.Elastic, Enum.EasingDirection.InOut)	

		-- Fast, shaky wobble	
		TweenService:Create(button, info, {Rotation = -20}):Play()	
		task.wait(0.05)	
		TweenService:Create(button, info, {Rotation = 20}):Play()	
		task.wait(0.05)	
		TweenService:Create(button, info, {Rotation = -10}):Play()	
		task.wait(0.05)	
		TweenService:Create(button, info, {Rotation = 0}):Play()	
	end	

	button.MouseButton1Click:Connect(function()	
		clicks = clicks + 1	

		if label then	
			-- Pick a random word from the list	
			local randomWord = tickleWords[math.random(1, #tickleWords)]	
			label.Text = randomWord .. " ("..clicks..")"	
		end	

		-- Trigger the tickle wobble	
		doTickleWobble()	
	end)	
end;
